div.textarea:
skinparam ranksep 20
skinparam dpi 125
<style>
  rectangle {
    HorizontalAlignment: left;
  }
</style>

rectangle "Main" {
  (main.view)
  (singleton)
}
rectangle "Base" {
  (base.component)
  (component)
  (model)
}
rectangle "<b>main.ts</b>" as main_ts

(component) ..> (base.component)
main_ts ==> (main.view)
(main.view) --> (component)
(main.view) ...> (singleton)
(singleton) ---> (model)

